const dict = new Map<string, string[]>(rows.map((r) => [r[0], r]));

let current: Language = "en";

/** Picks the closest supported language for a BCP 47 tag like "zh-CN" or "pt-BR". */
export function resolveLanguage(pref: LanguagePref): Language {
  if (pref !== "system") return pref;
  const tag = (navigator.language || "en").toLowerCase().split("-")[0];
  return (order as string[]).includes(tag) ? (tag as Language) : "en";
}

export function setLanguage(lang: Language) {
  current = lang;
  document.documentElement.lang = lang === "zh" ? "zh-CN" : lang;
}

/** Translates an English UI string, filling {name} placeholders. Unknown strings come back in English. */
/** Rows with {placeholders}, matched against text that was formatted before it reached t(), such as
    a stage name from the backend ("Installing Forge") or an option value ("12 chunks"). */
const patterns = rows
  .filter((r) => r[0].includes("{"))
  .map((r) => {
    const names: string[] = [];
    const source = r[0]
      .split(/(\{\w+\})/)
      .map((p) => {
        const m = /^\{(\w+)\}$/.exec(p);
        if (!m) return p.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
        names.push(m[1]);
        return "(.+?)";
      })
      .join("");
    return { re: new RegExp(`^${source}$`), names, row: r };
  });

type Hit = { row: string[]; vars?: Record<string, string> } | null;
/** Pattern matches are remembered, since the same text is translated on every render. */
const matched = new Map<string, Hit>();

function lookup(en: string): Hit {
  const row = dict.get(en);
  if (row) return { row };
  if (matched.has(en)) return matched.get(en)!;
  let hit: Hit = null;
  for (const p of patterns) {
    const m = p.re.exec(en);
    if (m) {
      hit = { row: p.row, vars: Object.fromEntries(p.names.map((n, i) => [n, m[i + 1]])) };
      break;
    }
  }
  if (matched.size < 2000) matched.set(en, hit);
  return hit;
}

export function t(en: string, vars?: Record<string, string | number>): string {
  const hit = current === "en" ? null : lookup(en);
  let s = (hit && hit.row[order.indexOf(current)]) || en;
  if (hit?.vars) for (const [k, v] of Object.entries(hit.vars)) s = s.split(`{${k}}`).join(v);
  if (vars) for (const [k, v] of Object.entries(vars)) s = s.split(`{${k}}`).join(String(v));
  return s;
}

/** Like t(), but placeholders can be elements, e.g. a <kbd> inside a sentence. */
export function tNode(en: string, nodes: Record<string, ReactNode>): ReactNode {
  const parts = t(en).split(/(\{\w+\})/);
  return createElement(
    Fragment,
    null,
    ...parts.map((p) => {
      const m = /^\{(\w+)\}$/.exec(p);
      return m && m[1] in nodes ? nodes[m[1]] : p;
    }),
  );
}
